/* MotoKare Phase 1–2: responsive HUD-themed frontend prototype.
   All data and authentication are local, demonstrative only. No backend is connected. */
(() => {
  'use strict';
  const $ = (selector, root = document) => root.querySelector(selector);
  const app = $('#app');
  const modalRoot = $('#modal-root');
  const toastRoot = $('#toast-root');
  const KEY = 'motokare-fui-v1';
  const now = new Date();
  const dateShift = n => { const d = new Date(); d.setDate(d.getDate() + n); return d.toISOString().slice(0, 10); };
  const today = () => new Date().toISOString().slice(0, 10);
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const cash = n => '₱' + Number(n || 0).toLocaleString('en-PH', {maximumFractionDigits: 0});
  const num = n => Number(n || 0).toLocaleString('en-PH');
  const niceDate = d => d ? new Date(d + 'T12:00:00').toLocaleDateString('en-US', {month:'short',day:'numeric',year:'numeric'}) : '—';
  const uid = () => (typeof crypto !== 'undefined' && crypto.randomUUID ? crypto.randomUUID() : 'id' + Math.random().toString(36).slice(2));
  const icoPaths = {
    bike:'<circle cx="5.5" cy="17.5" r="3.5"/><circle cx="18.5" cy="17.5" r="3.5"/><path d="m5.5 17.5 4-9h5l4 9M10 8.5l-2-2H5M14.5 8.5l-3 9h-6M14.5 8.5 18.5 17.5"/>',
    dashboard:'<rect x="3" y="3" width="7" height="9" rx="1"/><rect x="14" y="3" width="7" height="5" rx="1"/><rect x="14" y="12" width="7" height="9" rx="1"/><rect x="3" y="16" width="7" height="5" rx="1"/>',
    calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/><path d="m8 15 2 2 5-5"/>',
    wrench:'<path d="M14.5 6a5 5 0 0 0-6.4 6.4L3 17.5a2.5 2.5 0 0 0 3.5 3.5l5.1-5.1A5 5 0 0 0 18 9.5l-4 2-3-3z"/>',
    history:'<path d="M3 12a9 9 0 1 0 3-6.7L3 8"/><path d="M3 3v5h5M12 7v5l4 2"/>',
    users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8ZM22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>',
    bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',
    settings:'<path d="M12 2v2m0 16v2M4.93 4.93l1.42 1.42m11.3 11.3 1.42 1.42M2 12h2m16 0h2M4.93 19.07l1.42-1.42m11.3-11.3 1.42-1.42"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="2"/>',
    plus:'<path d="M12 5v14M5 12h14"/>', arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>', left:'<path d="M19 12H5m6-6-6 6 6 6"/>',
    menu:'<path d="M4 6h16M4 12h16M4 18h16"/>', x:'<path d="M5 5l14 14M19 5 5 19"/>',
    logout:'<path d="M10 17l5-5-5-5m5 5H3M12 3h7a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-7"/>',
    clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',
    chevron:'<path d="m9 18 6-6-6-6"/>', down:'<path d="m6 9 6 6 6-6"/>',
    info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v6M12 7h.01"/>',
    alert:'<path d="m12 3 10 18H2L12 3zM12 9v5M12 18h.01"/>',
    check:'<path d="m5 12 4 4L19 6"/>',
    checkCircle:'<circle cx="12" cy="12" r="10"/><path d="m7 12 3 3 7-7"/>',
    clipboard:'<rect x="5" y="4" width="14" height="18" rx="2"/><rect x="9" y="2" width="6" height="4" rx="1"/><path d="M9 12h6M9 16h6"/>',
    chart:'<path d="M3 3v18h18M7 16v-5M12 16V7M17 16v-8"/>',
    shield:'<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/><path d="m9 12 2 2 4-4"/>',
    target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',
    location:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2"/>',
    speed:'<path d="M12 14l5-5M4 18a10 10 0 1 1 16 0H4Z"/><circle cx="12" cy="14" r="1"/>',
    bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-7l1-7z"/>',
    store:'<path d="M3 10V7l2-4h14l2 4v3M3 10a3 3 0 0 0 6 0 3 3 0 0 0 6 0 3 3 0 0 0 6 0M5 13v8h14v-8M9 21v-6h6v6"/>',
    send:'<path d="m22 2-7 20-4-9-9-4 20-7ZM22 2 11 13"/>',
    file:'<path d="M13 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9zM13 2v7h7M8 14h8M8 18h8"/>',
    power:'<path d="M12 2v10M5.5 5.5a9 9 0 1 0 13 0"/>',
    user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',
    filter:'<path d="M4 5h16l-6 7v7l-4 2v-9L4 5z"/>',
    edit:'<path d="M12 20h9M16 4l4 4-11 11H5v-4L16 4z"/>',
    trash:'<path d="M3 6h18M8 6V4h8v2M6 6l1 15h10l1-15M10 10v7M14 10v7"/>',
    download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',
  };
  function icon(name, cls='') { return `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icoPaths[name]||icoPaths.info}</svg>`; }
  function logo(){return `<a class="brand" href="#/" aria-label="MotoKare home"><span class="brand-emblem"><svg viewBox="0 0 48 48" width="38" height="38" fill="none" stroke="currentColor" stroke-width="2"><path d="M24 3 44 14v20L24 45 4 34V14Z"/><path d="M12 30V18l12 12 12-12v12M12 18l12 12 12-12"/><path d="M24 3v6M24 39v6"/></svg></span><span>MOTO<span>KARE</span></span></a>`;}
  function blueprint(extraClass='') { return `<svg class="${extraClass}" viewBox="0 0 640 340" fill="none" role="img" aria-label="Technical line illustration of a motorcycle">
    <g stroke="#053949" opacity=".7" stroke-width="1"><path d="M0 170h640M320 0v340M0 80h640M0 260h640" stroke-dasharray="3 10"/><circle cx="322" cy="170" r="149" stroke-dasharray="3 8"/><path d="M60 30h520M60 310h520"/></g>
    <g class="line-draw" stroke="#00FFFF" fill="none" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round">
      <circle pathLength="1" cx="135" cy="240" r="70"/><circle pathLength="1" cx="510" cy="240" r="70"/><circle pathLength="1" cx="135" cy="240" r="52" opacity=".55"/><circle pathLength="1" cx="510" cy="240" r="52" opacity=".55"/>
      <path pathLength="1" d="M135 240 243 239 300 157 393 178 510 240M243 239l-35-88h81l25 47-71 41m71-41 79-20-36 62H243"/>
      <path pathLength="1" d="M300 157h-77l-29-29-47 1-10 20h93l18 23M218 128l27-20h82l36 26 30 44"/>
      <path pathLength="1" d="M393 178 436 116h62l19 22-27 19-34-15-63 36M447 115l-22-26 7-8h52M458 78h39M484 82l28-14M517 68h23"/>
      <path pathLength="1" d="M310 175h61l-25 65h-47l-26-32M276 206l25 17h48M254 178l-35 60m91-64 30 55"/>
      <path pathLength="1" d="M141 169 155 139l-23-21-32 2M427 117l20 49M160 179l77-35M435 154l52 20"/>
      <path pathLength="1" d="M102 239h68M135 205v69M477 240h66M510 205v70" opacity=".55"/><path pathLength="1" d="M60 247 33 256M570 246l31 12"/>
    </g><g fill="#00FFFF" opacity=".9"><circle cx="135" cy="240" r="4"/><circle cx="510" cy="240" r="4"/><circle cx="300" cy="157" r="3"/><circle cx="393" cy="178" r="3"/></g><g fill="#86BDCA" font-size="10" font-family="monospace"><text x="46" y="55">FIG 01 // CHASSIS OVERVIEW</text><text x="445" y="303">MOTORCYCLE // SYS</text><text x="302" y="52">0 1 0 1 0</text></g></svg>`; }
  const componentCatalog=[
    {name:'Engine Oil',icon:'bolt',interval:2000,last:10600,days:12},
    {name:'Brake Inspection',icon:'shield',interval:4500,last:9500,days:40},
    {name:'Air Filter',icon:'filter',interval:6000,last:9200,days:95},
    {name:'Chain & Sprocket',icon:'settings',interval:2100,last:11400,days:25},
    {name:'Battery Check',icon:'bolt',interval:7000,last:11000,days:130},
    {name:'Tire Inspection',icon:'target',interval:4700,last:10000,days:65}
  ];
  const seed = () => ({
    version:1, session:null, role:'rider', selectedBike:'bike-1',
    bikes:[{id:'bike-1',model:'Yamaha Mio i125',year:2023,plate:'RDX 4821',odometer:12450,updated:today()}],
    components:componentCatalog.map((c,i)=>({id:'c-'+i,bikeId:'bike-1',name:c.name,icon:c.icon,interval:c.interval,lastKm:c.last,nextKm:c.last+c.interval,dueDate:dateShift(c.days)})),
    services:[
      {id:'s1',bikeId:'bike-1',type:'Engine Oil',date:dateShift(-61),mileage:10600,cost:450,shop:'M. Reyes Motors',notes:'Engine oil replaced'},
      {id:'s2',bikeId:'bike-1',type:'Brake Inspection',date:dateShift(-90),mileage:9500,cost:700,shop:'MotoCare Garage',notes:'Front brake pads inspected'},
      {id:'s3',bikeId:'bike-1',type:'Air Filter',date:dateShift(-100),mileage:9200,cost:380,shop:'M. Reyes Motors',notes:'Air filter cleaned'}
    ],
    customers:[
      {id:'u1',name:'Carlos Mendoza',contact:'carlos@example.com',motorcycle:'Honda Click 125i',odometer:18420,lastVisit:dateShift(-5)},
      {id:'u2',name:'Andrea Santos',contact:'andrea@example.com',motorcycle:'Yamaha NMAX',odometer:9800,lastVisit:dateShift(-12)},
      {id:'u3',name:'Miguel Reyes',contact:'miguel@example.com',motorcycle:'Suzuki Raider R150',odometer:26500,lastVisit:dateShift(-18)},
      {id:'u4',name:'Jasmine Cruz',contact:'jasmine@example.com',motorcycle:'Honda Beat',odometer:6700,lastVisit:dateShift(-22)}
    ],
    jobs:[
      {id:'j1',customerId:'u1',service:'Engine Oil + Filter',date:today(),status:'In Progress',cost:850},
      {id:'j2',customerId:'u2',service:'CVT Cleaning',date:today(),status:'Pending',cost:1200},
      {id:'j3',customerId:'u3',service:'Brake Inspection',date:dateShift(-1),status:'Completed',cost:560},
      {id:'j4',customerId:'u4',service:'General Tune-up',date:dateShift(-2),status:'Completed',cost:950}
    ],
    appointments:[
      {id:'a1',customerId:'u2',service:'CVT Cleaning',date:dateShift(1),time:'09:30',status:'Confirmed'},
      {id:'a2',customerId:'u1',service:'Oil Change',date:dateShift(2),time:'13:00',status:'Confirmed'},
      {id:'a3',customerId:'u4',service:'Tire Inspection',date:dateShift(3),time:'10:00',status:'Pending'}
    ],
    settings:{notifications:true,distance:'km',shopName:'MotoKare Service Hub'}
  });
  let state;
  try {state = {...seed(),...JSON.parse(localStorage.getItem(KEY) || 'null')};} catch(_) {state=seed();}
  // Validation protects the frontend from stale, unexpected local data formats.
  if (!Array.isArray(state.bikes)||!Array.isArray(state.components)||!Array.isArray(state.services)||!Array.isArray(state.customers)||!Array.isArray(state.jobs)||!Array.isArray(state.appointments)) state=seed();
  function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch(_){toast('Local storage unavailable; changes are temporary.');}}
  let route='', mobileOpen=false, notifyOpen=false, toastTimer;
  const routesRider=[['dashboard','Dashboard','dashboard'],['motorcycles','My Motorcycles','bike'],['components','Components','settings'],['maintenance','Maintenance','calendar'],['history','Service History','history'],['settings','Settings','settings']];
  const routesShop=[['dashboard','Shop Dashboard','dashboard'],['customers','Customers','users'],['jobs','Service Jobs','wrench'],['appointments','Appointments','calendar'],['reports','Reports','chart'],['settings','Settings','settings']];
  const routeNow=()=> (location.hash.slice(1).split('?')[0] || '/');
  const parseAppRoute = path => {const a=path.split('/').filter(Boolean);return {role:a[0]==='shop'?'shop':'rider',page:a[1]||'dashboard'};};
  function navigate(path){location.hash='#'+path; if(routeNow()===path) render();}
  function ensureBike(){let bike=state.bikes.find(x=>x.id===state.selectedBike);if(!bike){bike=state.bikes[0];state.selectedBike=bike?.id??null;}return bike;}
  const activeComps = id => state.components.filter(c=>c.bikeId===id);
  function health(c,bike){
    let days=Math.ceil((new Date(c.dueDate+'T12:00:00')-new Date(today()+'T12:00:00'))/86400000);
    const delta=c.nextKm-bike.odometer;
    const overdue=delta<=0 || days<0;
    const soon=!overdue&&(delta<=300||days<=14);
    const pct=Math.max(0,Math.min(100,Math.round(100*delta/Math.max(1,c.interval))));
    return {days,delta,pct,kind:overdue?'danger':soon?'warn':'good',label:overdue?'Overdue':soon?'Service Soon':'On Track'};
  }
  function alertsForBike(bike){return bike?activeComps(bike.id).map(c=>({c,...health(c,bike)})).filter(a=>a.kind!=='good'):[];}
  const allAlerts=()=>state.bikes.flatMap(b=>alertsForBike(b));
  const totalCosts=bike=>state.services.filter(s=>s.bikeId===bike?.id).reduce((a,s)=>a+Number(s.cost||0),0);
  function toast(msg){clearTimeout(toastTimer);toastRoot.innerHTML=`<div class="toast">${icon('checkCircle')} ${esc(msg)}</div>`;toastTimer=setTimeout(()=>toastRoot.innerHTML='',3600);}
  function ticker(){return `<div class="ticker" aria-label="MotoKare system information"><span class="ticker-track">MOTOKARE // MAINTENANCE INTELLIGENCE <span class="sep">✦</span> RIDER AND WORKSHOP SYSTEMS <span class="sep">✦</span> SCHEDULE-BASED TRACKING <span class="sep">✦</span> DEMONSTRATION ENVIRONMENT <span class="sep">✦</span> RIDE SMART. MAINTAIN BETTER.</span></div>`;}
  function landingHeader(){return `<header class="site-header"><div class="container nav-inner">${logo()}<nav class="nav-links" id="site-nav" aria-label="Main navigation"><a href="#/" data-scroll="home">Home</a><a href="#/" data-scroll="features">Features</a><a href="#/" data-scroll="roles">Who It's For</a><a href="#/" data-scroll="how">How It Works</a><a href="#/" data-scroll="pricing">Pricing</a></nav><div class="nav-actions"><a class="button ghost small" href="#/login">Log In</a><a class="button small primary" href="#/register">Get Started ${icon('arrow')}</a><button class="nav-menu-toggle" type="button" aria-label="Toggle navigation" aria-expanded="false" data-action="mobile-nav">${icon('menu')}</button></div></div></header>`;}
  function landing(){
    const features=[['calendar','Maintenance Scheduling','Stay ahead of oil changes, brake checks, and service intervals with one digital schedule.'],['bell','Intelligent Reminders','Get clear service-due indicators based on recorded dates and odometer readings.'],['history','Service History','Maintain an organized timeline of past servicing, repair expenses, and workshops.'],['speed','Mileage Tracking','Update your odometer to estimate which motorcycle components are due for attention.'],['store','Repair Shop Workspace','Keep customer records, manage service jobs, and plan upcoming appointments.'],['chart','Maintenance Reports','See historical service activity and cost summaries in a streamlined dashboard.']];
    return `${landingHeader()}<main id="main"><section class="hero" id="home"><div class="container hero-layout"><div><div class="kicker"><span class="status-dot"></span> MOTORCYCLE MAINTENANCE // REIMAGINED</div><h1 class="hero-title"><span>YOUR RIDE.</span><span class="accent">UNDER</span><span>CONTROL.</span></h1><p class="hero-desc">The next-generation maintenance command center for motorcycle riders and repair shops. Track your bike, plan every service, and keep your maintenance history on one connected platform.</p><div class="hero-actions"><a class="button primary" href="#/register">INITIALIZE YOUR ACCOUNT ${icon('arrow')}</a><a class="button" href="#/rider/dashboard">EXPLORE LIVE DEMO ${icon('chevron')}</a></div><div class="hero-proof"><div class="proof-item"><strong>01</strong><span>Track your ride</span></div><div class="proof-item"><strong>02</strong><span>Never miss service</span></div><div class="proof-item"><strong>03</strong><span>Connect your shop</span></div></div></div><div class="hero-visual"><div class="radar-ring" aria-hidden="true"></div><div class="radar-sweep" aria-hidden="true"></div>${blueprint('bike-svg')}<div class="spec top"><small>VEHICLE STATUS</small><div class="val">ONLINE</div><div class="system-status"><span class="status-dot ok"></span> SYSTEM READY</div></div><div class="spec bottom"><small>DEMO ODOMETER</small><div class="val">12,450 <span style="font-size:13px">KM</span></div><small>MAINTENANCE ANALYTICS</small></div><span class="frame-corner left">MK // TECH-01</span><span class="frame-corner right">[ 001 : ACTIVE ]</span></div></div></section>${ticker()}
    <section id="features" class="section"><div class="container"><div class="section-heading"><div><div class="kicker"><span class="eyeline"></span> SYSTEM CAPABILITIES</div><h2 class="section-title">ENGINEERED FOR<br><span class="text-cyan">EVERY RIDE.</span></h2></div><p class="section-lead">Everything your motorcycle needs, from its first logged kilometer to its next service appointment.</p></div><div class="feature-grid">${features.map((f,i)=>`<article class="panel feature"><div class="feature-index">MOD_0${i+1}</div><div class="feature-icon">${icon(f[0],'large')}</div><h3>${f[1]}</h3><p>${f[2]}</p></article>`).join('')}</div></div></section>
    <section id="roles" class="section darkstripe"><div class="container"><div class="section-heading"><div><div class="kicker"><span class="eyeline"></span> TWO CONNECTED EXPERIENCES</div><h2 class="section-title">ONE PLATFORM.<br><span class="text-cyan">TWO COMMAND CENTERS.</span></h2></div></div><div class="role-grid"><article class="panel role-panel"><div class="role-sigil">${icon('bike')} MODE // B2C - RIDER</div><h3>MAINTAIN<br>WITH CONFIDENCE.</h3><p>Your motorcycle's complete service schedule, odometer tracking, maintenance alerts, and repair history in one organized place.</p><div class="role-cta"><a class="button primary" href="#/rider/dashboard">PREVIEW RIDER SYSTEM ${icon('arrow')}</a></div></article><article class="panel role-panel shop"><div class="role-sigil">${icon('store')} MODE // B2B - WORKSHOP</div><h3>MANAGE<br>EVERY SERVICE.</h3><p>Organize customer motorcycles, service jobs, upcoming appointments, and your shop's maintenance records.</p><div class="role-cta"><a class="button" href="#/shop/dashboard">PREVIEW SHOP SYSTEM ${icon('arrow')}</a></div></article></div></div></section>
    <section id="how" class="section"><div class="container"><div class="section-heading"><div><div class="kicker"><span class="eyeline"></span> OPERATION SEQUENCE</div><h2 class="section-title">FOUR STEPS.<br><span class="text-cyan">FULL CONTROL.</span></h2></div></div><div class="steps">${[['01','REGISTER','Create a rider or repair-shop account.'],['02','SET UP','Add motorcycle details and a starting odometer.'],['03','MONITOR','Review service intervals, schedules, and alerts.'],['04','MAINTAIN','Log service work and update maintenance history.']].map(x=>`<article class="panel step"><span class="step-no">${x[0]}</span><h3>${x[1]}</h3><p>${x[2]}</p></article>`).join('')}</div></div></section>
    <section id="pricing" class="section darkstripe"><div class="container"><div class="section-heading"><div><div class="kicker"><span class="eyeline"></span> DEPLOYMENT OPTIONS</div><h2 class="section-title">CHOOSE YOUR<br><span class="text-cyan">SERVICE TIER.</span></h2></div><p class="section-lead">Illustrative pricing based on the MotoKare business proposal; payments are not active in this prototype.</p></div><div class="pricing-grid"><article class="panel price-card"><div class="label">RIDER // FREE</div><div class="price">₱0 <small>/ START</small></div><p>Explore the core maintenance workflow and digital motorcycle tracking experience.</p><a class="button" href="#/register">CREATE ACCOUNT ${icon('arrow')}</a></article><article class="panel price-card"><div class="label">RIDER // PREMIUM</div><div class="price">₱199 <small>/ YEAR</small></div><p>Proposed paid plan for individual riders who want an extended maintenance experience.</p><a class="button primary" href="#/register">GET STARTED ${icon('arrow')}</a></article><article class="panel price-card"><div class="label">WORKSHOP // BUSINESS</div><div class="price">₱2,999 <small>/ YEAR</small></div><p>Proposed repair-shop workspace with customers, service jobs, and appointment records.</p><a class="button" href="#/register">SET UP WORKSHOP ${icon('arrow')}</a></article></div><div class="pricing-note">* These figures are planning assumptions. No subscriptions, checkout, or real payment processing are implemented.</div></div></section>
    </main><footer class="site-footer"><div class="container footer-inner">${logo()}<span>© ${now.getFullYear()} MotoKare • Ride Smart. Maintain Better.</span><span>PHASE 01–02 // FRONTEND DEMO</span></div></footer>`;
  }
  function authPage(mode){const register=mode==='register'; const role=state.role==='shop'?'shop':'rider';return `<main id="main" class="auth-shell"><section class="auth-promo">${logo()}<div><div class="kicker"><span class="status-dot"></span> SYSTEM ACCESS // SECURE PORTAL CONCEPT</div><h1>${register?'JOIN THE<br><span>NETWORK.</span>':'WELCOME<br><span>BACK.</span>'}</h1><p>Everything you need to track motorcycle care, maintain service records, and connect riders with repair shops. Enter your MotoKare workspace.</p>${blueprint('blueprint-mini')}</div><div class="auth-foot"><span>MOTOKARE // AUTH MODULE</span><span>ENCRYPTED DESIGN AESTHETIC • DEMO ONLY</span></div></section><section class="auth-main"><div class="auth-card"><a class="auth-back" href="#/">${icon('left')} RETURN TO HOMEPAGE</a><div class="label" style="margin-top:39px">ACCESS TERMINAL // ${register?'REGISTER':'LOGIN'}</div><h2>${register?'Create Account':'System Login'}</h2><p class="auth-sub">${register?'Select an account type and set up your workspace.':'Select your access type to enter your dashboard.'}</p><div class="auth-notice">${icon('info')} Frontend demonstration only. Credentials are not verified or sent to a server. Do not enter a real password.</div><form data-form="${register?'register':'login'}" id="auth-form"><div class="label" style="margin-bottom:10px">SELECT ACCESS MODE</div><div class="tabs" role="group" aria-label="Account type"><button type="button" class="tab ${role==='rider'?'active':''}" aria-pressed="${role==='rider'}" data-action="auth-role" data-role="rider">${icon('bike')} RIDER / B2C</button><button type="button" class="tab ${role==='shop'?'active':''}" aria-pressed="${role==='shop'}" data-action="auth-role" data-role="shop">${icon('store')} WORKSHOP / B2B</button></div>${register?`<div class="field"><label for="full-name">Full name</label><input id="full-name" name="fullName" autocomplete="name" placeholder="Your full name" minlength="2" required></div>`:''}<div class="field"><label for="auth-email">Email address</label><input id="auth-email" name="email" type="email" autocomplete="email" placeholder="name@example.com" required></div><div class="field"><label for="auth-password">${register?'Create demo password':'Demo password'}</label><input id="auth-password" name="password" type="password" autocomplete="${register?'new-password':'current-password'}" placeholder="At least 6 characters (demo only)" minlength="6" required></div>${register&&role==='shop'?`<div class="field"><label for="shop-name">Workshop name</label><input id="shop-name" name="shopName" placeholder="e.g. MotoKare Service Hub" required></div>`:''}<button class="button primary full" type="submit">${register?'CREATE DEMO ACCOUNT':'ENTER DASHBOARD'} ${icon('arrow')}</button></form><p class="auth-helper">${register?'Already have an account?':'New to MotoKare?'} <a href="#/${register?'login':'register'}">${register?'Log in':'Create account'}</a></p><div class="auth-helper"><a href="#/rider/dashboard">Preview rider dashboard</a> &nbsp;·&nbsp; <a href="#/shop/dashboard">Preview shop dashboard</a></div></div></section></main>`;}
  function sidebar(role,page){const items=role==='shop'?routesShop:routesRider;return `<aside class="sidebar ${mobileOpen?'open':''}" id="app-sidebar" aria-label="${role==='shop'?'Workshop':'Rider'} navigation">${logo()}<div><div class="side-caption">${role==='shop'?'WORKSHOP OPERATIONS':'RIDER CONTROL CENTER'}</div><nav class="side-nav" aria-label="Dashboard sections"><div class="nav-group">Main Menu // 01</div>${items.map(([id,name,ic])=>`<a href="#/${role}/${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(ic)} ${name}</a>`).join('')}</nav></div><div class="sidebar-spacer"></div><button type="button" class="side-switch" data-action="switch-role" data-role="${role==='shop'?'rider':'shop'}" aria-label="Switch to ${role==='shop'?'rider':'workshop'} demo"><span><small>SWITCH WORKSPACE</small><strong>${role==='shop'?'Rider Dashboard':'Repair Shop Dashboard'}</strong></span>${icon('arrow')}</button><button class="button ghost small full" type="button" data-action="logout">${icon('logout')} EXIT TO HOME</button><div class="side-foot">BUILD 01.02.26 // DEMO MODE</div></aside>`;}
  function breadcrumb(page){return page.replace(/-/g,' ').replace(/\b\w/g,c=>c.toUpperCase());}
  function topbar(role,page){const count=role==='shop'?state.appointments.filter(x=>x.status==='Pending').length:allAlerts().length;return `<header class="app-topbar"><div style="display:flex;align-items:center;gap:15px"><button class="icon-button sidebar-mobile-toggle" type="button" data-action="sidebar-toggle" aria-label="Open sidebar navigation" aria-expanded="${mobileOpen}">${icon('menu')}</button><div class="breadcrumbs">MOTOKARE / <span>${role==='shop'?'WORKSHOP':'RIDER'} / ${esc(breadcrumb(page))}</span></div></div><div class="topbar-actions"><span class="system-status"><span class="status-dot ok"></span> LOCAL DEMO ACTIVE</span><button class="icon-button" type="button" data-action="notifications" aria-label="View notifications" aria-expanded="${notifyOpen}">${icon('bell')}${count?`<span class="notify-count">${count>9?'9+':count}</span>`:''}</button><div class="top-avatar" aria-hidden="true">${esc((state.session?.name||'MK').slice(0,2).toUpperCase())}</div><div class="top-user">${esc(state.session?.name||'Demo Operator')}<small>${role==='shop'?'WORKSHOP MODE':'RIDER MODE'}</small></div></div></header>`;}
  function appShell(role,page,content){state.role=role;save();document.body.classList.toggle('app-mode',true);return `<div class="app-layout">${sidebar(role,page)}<div class="mobile-shade ${mobileOpen?'show':''}" data-action="sidebar-close"></div><div class="app-body">${topbar(role,page)}${ticker()}<main id="main" class="app-content">${content}</main></div></div>`;}
  const head=(tag,title,desc,buttons='')=>`<header class="page-head"><div><div class="label">${tag}</div><h1>${title}</h1><p>${desc}</p></div>${buttons?`<div class="page-actions">${buttons}</div>`:''}</header>`;
  const button=(action,title,ic='plus',primary=true)=>`<button type="button" class="button ${primary?'primary':''} small" data-action="${action}">${icon(ic)} ${title}</button>`;
  function metric(label,value,unit,ic){return `<div class="panel metric"><div style="display:flex;align-items:center;justify-content:space-between"><div class="label">${label}</div><span class="metric-icon">${icon(ic)}</span></div><div class="readout">${value} ${unit?`<small>${unit}</small>`:''}</div></div>`;}
  function componentRows(bike,compact=true){const comps=activeComps(bike.id);return `<div class="component-list">${comps.slice(0,compact?4:comps.length).map(c=>{const h=health(c,bike);return `<div class="component-row"><div class="comp-icon">${icon(c.icon)}</div><div><div class="comp-row-title"><strong>${esc(c.name)}</strong><small>${h.delta<=0?`${num(Math.abs(h.delta))} km past interval`:`${num(h.delta)} km to interval`}</small></div><div class="bar-track" role="progressbar" aria-label="${esc(c.name)} estimated interval remaining" aria-valuenow="${h.pct}" aria-valuemin="0" aria-valuemax="100"><div class="bar-fill ${h.kind}" style="width:${h.pct}%"></div></div></div><span class="comp-status ${h.kind}">${h.label}</span></div>`}).join('')}</div>`;}
  const noBike = () => `<div class="panel empty-state">${icon('bike','xl')}<h3>No motorcycles yet</h3><p>Add your first motorcycle to start tracking its maintenance schedule.</p>${button('add-bike','Add Motorcycle')}</div>`;
  function riderDash(){const bike=ensureBike();if(!bike)return head('RIDER // OVERVIEW','Dashboard','Your motorcycle command center.')+noBike();const comps=activeComps(bike.id),alarms=alertsForBike(bike),next=comps.map(c=>({...c,rem:c.nextKm-bike.odometer})).sort((a,b)=>a.rem-b.rem)[0];const services=state.services.filter(s=>s.bikeId===bike.id).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,3);
    return `${head('RIDER // SYSTEM OVERVIEW','Command Center','Your motorcycle. Your maintenance. Complete control.',`<button class="button small ghost" data-action="add-bike">${icon('plus')} ADD BIKE</button>${button('update-mileage','UPDATE ODOMETER','speed')}`)}<div class="dashboard-grid"><section class="panel moto-profile"><div><div class="label">PRIMARY VEHICLE // ACTIVE</div><h2>${esc(bike.model)}</h2><p>${esc(bike.year)} model • Plate ${esc(bike.plate||'Not entered')}</p><div class="bike-id">UNIT ID // ${esc(bike.id.slice(-7).toUpperCase())}</div><div style="margin-top:13px"><span class="pill good"><span class="status-dot ok static"></span> PROFILE ACTIVE</span></div></div>${blueprint('blueprint-small')}</section><section class="panel status-panel ${alarms.length?'warning':'success'}"><div class="maintenance-flag"><span class="label">MAINTENANCE WATCH</span>${icon('alert','large')}</div><div><div class="alert-number" style="${alarms.length?'':'color:#A2FFA6;text-shadow:none'}">${String(alarms.length).padStart(2,'0')}</div><div class="label">${alarms.length?'SERVICE ITEMS NEED ATTENTION':'ALL SERVICE ITEMS ON TRACK'}</div><div class="progress-track"><div class="progress-bar" style="width:${Math.round(100*(comps.length-alarms.length)/Math.max(1,comps.length))}%"></div></div><small>Based on manually entered mileage and service intervals.</small></div><a class="linkline" href="#/rider/maintenance">VIEW MAINTENANCE ${icon('arrow')}</a></section></div><div class="metric-grid">${metric('CURRENT ODOMETER',num(bike.odometer),'KM','speed')}${metric('OPEN ALERTS',String(alarms.length).padStart(2,'0'),'ITEMS','alert')}${metric('NEXT SERVICE',num(Math.max(0,next?.rem??0)),'KM','calendar')}${metric('SERVICE SPENDING',cash(totalCosts(bike)),'','chart')}</div><div class="content-grid"><section class="panel"><div class="panel-head"><div><div class="label">SERVICE INTERVAL STATUS</div><h2>Component Health <span style="font-size:12px;color:var(--muted);font-family:var(--mono)">// ESTIMATED</span></h2></div><a class="linkline" href="#/rider/components">ALL ${icon('chevron')}</a></div>${componentRows(bike)}<div class="quick-actions"><button class="button small" data-action="log-service">${icon('plus')} LOG SERVICE</button></div></section><section class="panel"><div class="panel-head"><div><div class="label">EVENT LOG // RECENT</div><h2>Service History</h2></div><a class="linkline" href="#/rider/history">VIEW ALL ${icon('chevron')}</a></div>${services.length?services.map(s=>`<div class="service-mini"><span class="mini-marker">${icon('wrench')}</span><span><strong>${esc(s.type)}</strong><small>${niceDate(s.date)} • ${esc(s.shop)}</small></span><span class="cost">${cash(s.cost)}</span></div>`).join(''):'<p class="text-muted">No service records yet.</p>'}<div class="quick-actions"><button class="button small" data-action="log-service">${icon('plus')} ADD RECORD</button></div></section></div><p class="pricing-note" style="margin-top:17px">SYSTEM NOTE: Mileage and deadlines are manually maintained estimates, not live vehicle diagnostics or a safety certification.</p>`;
  }
  function motorcyclesPage(){return `${head('RIDER // GARAGE','My Motorcycles','Manage motorcycle profiles and odometer readings.',button('add-bike','ADD MOTORCYCLE'))}<div class="cards-grid">${state.bikes.map(b=>`<article class="panel vehicle-card"><div class="label">MOTORCYCLE PROFILE // ${b.id===state.selectedBike?'SELECTED':'STANDBY'}</div>${blueprint('blueprint-small')}<h3>${esc(b.model)}</h3><small>${esc(b.year)} • ${esc(b.plate||'No plate entered')}</small><div class="stat-mini"><span>ODOMETER</span><strong>${num(b.odometer)} KM</strong></div><div class="card-actions">${b.id===state.selectedBike?'<span class="pill good">ACTIVE</span>':`<button class="button small ghost" data-action="select-bike" data-id="${b.id}">SELECT BIKE</button>`}<button class="button small" data-action="edit-bike" data-id="${b.id}">${icon('edit')} EDIT</button></div></article>`).join('')}<button type="button" data-action="add-bike" class="panel vehicle-card empty-state" style="border-style:dashed;cursor:pointer;width:100%">${icon('plus','xl')}<h3>Add Another Motorcycle</h3><p>Track each bike's individual maintenance history.</p></button></div>`;}
  function componentsPage(){const b=ensureBike();return `${head('RIDER // TECHNICAL READOUT','Components','Track service intervals for each motorcycle component.',button('log-service','LOG SERVICE'))}${b?`<div class="alert-strip">${icon('info')} Estimated interval remaining is calculated from entered mileage and due dates. It does not measure mechanical condition.</div><section class="panel"><div class="panel-head"><div><div class="label">${esc(b.model.toUpperCase())} // ${num(b.odometer)} KM</div><h2>Service Interval Monitor</h2></div><span class="system-status"><span class="status-dot"></span> TRACKING ACTIVE</span></div>${componentRows(b,false)}<div class="quick-actions">${button('update-mileage','UPDATE MILEAGE','speed',false)}</div></section>`:noBike()}`;}
  function maintenancePage(){const b=ensureBike();const arr=b?activeComps(b.id).map(c=>({...c,h:health(c,b)})).sort((a,b)=>a.h.delta-b.h.delta):[];return `${head('RIDER // SCHEDULE CONTROL','Maintenance Schedule','Review service due dates and odometer-based intervals.',button('log-service','RECORD SERVICE'))}${!b?noBike():`<div class="alert-strip">${icon('alert')} Reminder indicators depend on manually maintained records and generic demo intervals; always follow your motorcycle manufacturer's service manual.</div><section class="panel table-panel"><div class="panel-head"><div><div class="label">UPCOMING MAINTENANCE MATRIX</div><h2>Scheduled Services</h2></div></div><table class="data-table"><thead><tr><th>Component</th><th>Next Mileage</th><th>Due Date</th><th>Remaining</th><th>Status</th></tr></thead><tbody>${arr.map(c=>`<tr><td><strong>${esc(c.name)}</strong></td><td>${num(c.nextKm)} KM</td><td>${niceDate(c.dueDate)}</td><td>${c.h.delta<=0?`${num(Math.abs(c.h.delta))} km over`:`${num(c.h.delta)} km`}</td><td><span class="pill ${c.h.kind}">${c.h.label}</span></td></tr>`).join('')}</tbody></table></section>`}`;}
  function historyPage(){const b=ensureBike();const entries=state.services.filter(x=>x.bikeId===b?.id).sort((a,c)=>c.date.localeCompare(a.date));return `${head('RIDER // MAINTENANCE ARCHIVE','Service History','Your saved repairs and maintenance expenses.',button('log-service','ADD SERVICE RECORD'))}${!b?noBike():`<div class="metric-grid">${metric('TOTAL RECORDS',num(entries.length),'ENTRIES','history')}${metric('LIFETIME SPEND',cash(totalCosts(b)),'','chart')}${metric('BIKE ODOMETER',num(b.odometer),'KM','speed')}${metric('VEHICLE',esc(String(b.year)),'MODEL YEAR','bike')}</div><section class="panel table-panel"><div class="panel-head"><div><div class="label">SERVICE ACTIVITY LOG</div><h2>Maintenance Entries</h2></div><button class="button small ghost" data-action="export-services">${icon('download')} EXPORT CSV</button></div>${entries.length?`<table class="data-table"><thead><tr><th>Date</th><th>Service</th><th>Mileage</th><th>Workshop</th><th>Cost</th></tr></thead><tbody>${entries.map(s=>`<tr><td>${niceDate(s.date)}</td><td><strong>${esc(s.type)}</strong>${s.notes?`<div class="text-muted" style="font-size:10px">${esc(s.notes)}</div>`:''}</td><td>${num(s.mileage)} KM</td><td>${esc(s.shop)}</td><td>${cash(s.cost)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty-state"><h3>No services recorded</h3><p>Start your maintenance timeline by adding a service entry.</p></div>'}</section>`}`;}
  function shopDash(){const total=state.customers.length,active=state.jobs.filter(j=>j.status!=='Completed').length,appointments=state.appointments.filter(x=>x.date>=today()).length,revenue=state.jobs.filter(j=>j.status==='Completed').reduce((a,j)=>a+j.cost,0);
    return `${head('WORKSHOP // OPERATIONS OVERVIEW','Service Command','Manage service operations and maintain customer relationships.',`${button('add-job','NEW SERVICE JOB','plus')}`)}<div class="shop-summary">${metric('REGISTERED RIDERS',num(total),'CUSTOMERS','users')}${metric('ACTIVE SERVICE JOBS',num(active),'JOBS','wrench')}${metric('UPCOMING BOOKINGS',num(appointments),'SLOTS','calendar')}${metric('COMPLETED JOB VALUE',cash(revenue),'DEMO','chart')}</div><div class="shop-overview"><section class="panel"><div class="panel-head"><div><div class="label">WORKSHOP ACTIVITY // DEMO DATA</div><h2>Service Volume</h2></div><span class="pill good">ONLINE</span></div><p class="text-muted" style="font-size:11px">Illustrative six-month service activity. Chart values are sample data, not measured analytics.</p><div class="shop-trend">${[41,58,46,72,61,87].map((n,i)=>`<div class="shop-bar-wrap"><div class="shop-bar" style="height:${n}%" title="Sample activity index: ${n}"></div><small>${['MAY','JUN','JUL','AUG','SEP','OCT'][i]}</small></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><div><div class="label">SYSTEM QUEUE</div><h2>Quick Operations</h2></div></div><div class="shop-activity"><div class="shop-activity-item">${icon('users')}<span><strong>Manage customers</strong><small>Register and update motorcycle owners.</small></span></div><div class="shop-activity-item">${icon('wrench')}<span><strong>Record service jobs</strong><small>Track repairs through completion.</small></span></div><div class="shop-activity-item">${icon('calendar')}<span><strong>Plan appointments</strong><small>Schedule customers and maintenance.</small></span></div></div><div class="quick-actions" style="margin-top:25px">${button('add-customer','ADD CUSTOMER','plus',false)}${button('add-appointment','BOOK SLOT','calendar',false)}</div></section></div><div class="content-grid"><section class="panel table-panel"><div class="panel-head"><div><div class="label">ACTIVE WORK ORDERS</div><h2>Current Jobs</h2></div><a class="linkline" href="#/shop/jobs">VIEW ALL ${icon('chevron')}</a></div>${jobsTable(state.jobs.slice(0,4),false)}</section><section class="panel"><div class="panel-head"><div><div class="label">CUSTOMER ACTIVITY</div><h2>Recent Customers</h2></div><a class="linkline" href="#/shop/customers">VIEW ALL ${icon('chevron')}</a></div>${state.customers.slice(0,4).map(c=>`<div class="service-mini"><span class="mini-marker">${icon('user')}</span><span><strong>${esc(c.name)}</strong><small>${esc(c.motorcycle)}</small></span></div>`).join('')}</section></div>`;
  }
  const customerName=id=>state.customers.find(c=>c.id===id)?.name || 'Unknown customer';
  function jobsTable(jobs,change=true){return jobs.length?`<table class="data-table"><thead><tr><th>Job ID / Rider</th><th>Service</th><th>Date</th><th>Status</th>${change?'<th>Action</th>':''}</tr></thead><tbody>${jobs.map(j=>`<tr><td><strong>#${esc(j.id.slice(0,6).toUpperCase())}</strong><div class="text-muted" style="font-size:10px">${esc(customerName(j.customerId))}</div></td><td>${esc(j.service)}</td><td>${niceDate(j.date)}</td><td><span class="pill ${j.status==='Completed'?'good':j.status==='In Progress'?'warn':'danger'}">${esc(j.status)}</span></td>${change?`<td>${j.status!=='Completed'?`<button class="button small ghost" data-action="advance-job" data-id="${esc(j.id)}">${j.status==='Pending'?'START':'COMPLETE'}</button>`:'<span class="text-muted">—</span>'}</td>`:''}</tr>`).join('')}</tbody></table>`:`<div class="empty-state"><h3>No jobs yet</h3><p>Add a service job to begin tracking work.</p></div>`;}
  function customersPage(){return `${head('WORKSHOP // CLIENT REGISTRY','Customers','Maintain digital customer and motorcycle profiles.',button('add-customer','ADD CUSTOMER'))}<div class="shop-summary">${metric('REGISTERED CUSTOMERS',num(state.customers.length),'RIDERS','users')}${metric('CUSTOMER MOTORCYCLES',num(state.customers.length),'BIKES','bike')}${metric('ACTIVE WORK ORDERS',num(state.jobs.filter(j=>j.status!=='Completed').length),'JOBS','wrench')}${metric('APPOINTMENT QUEUE',num(state.appointments.length),'TOTAL','calendar')}</div><section class="panel table-panel"><div class="panel-head"><div><div class="label">RIDER DIRECTORY</div><h2>Customer Records</h2></div></div>${state.customers.length?`<table class="data-table"><thead><tr><th>Customer</th><th>Motorcycle</th><th>Odometer</th><th>Last Visit</th><th>Contact</th></tr></thead><tbody>${state.customers.map(c=>`<tr><td><strong>${esc(c.name)}</strong></td><td>${esc(c.motorcycle)}</td><td>${num(c.odometer)} KM</td><td>${niceDate(c.lastVisit)}</td><td>${esc(c.contact)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty-state"><h3>No customers</h3></div>'}</section>`;}
  function jobsPage(){return `${head('WORKSHOP // SERVICE PROCESSOR','Service Jobs','Track and update repair and servicing work orders.',button('add-job','NEW JOB'))}<section class="panel table-panel"><div class="panel-head"><div><div class="label">WORK ORDER CONTROL</div><h2>Active & Completed Jobs</h2></div></div>${jobsTable(state.jobs)}</section>`;}
  function appointmentsPage(){return `${head('WORKSHOP // TIME CONTROL','Appointments','Schedule upcoming customer servicing.',button('add-appointment','BOOK APPOINTMENT'))}<section class="panel table-panel"><div class="panel-head"><div><div class="label">SCHEDULED SERVICE QUEUE</div><h2>Upcoming Appointments</h2></div></div>${state.appointments.length?`<table class="data-table"><thead><tr><th>Customer</th><th>Requested Service</th><th>Date</th><th>Time</th><th>Status</th><th>Action</th></tr></thead><tbody>${[...state.appointments].sort((a,b)=>a.date.localeCompare(b.date)).map(a=>`<tr><td><strong>${esc(customerName(a.customerId))}</strong></td><td>${esc(a.service)}</td><td>${niceDate(a.date)}</td><td>${esc(a.time)}</td><td><span class="pill ${a.status==='Confirmed'?'good':'warn'}">${esc(a.status)}</span></td><td>${a.status==='Pending'?`<button class="button small ghost" data-action="confirm-appointment" data-id="${a.id}">CONFIRM</button>`:'—'}</td></tr>`).join('')}</tbody></table>`:'<div class="empty-state"><h3>No appointments</h3></div>'}</section>`;}
  function reportsPage(){const jobs=state.jobs,done=jobs.filter(x=>x.status==='Completed'),val=done.reduce((a,x)=>a+Number(x.cost),0),avg=done.length?val/done.length:0;const row=[['Completed Services',done.length],['Open Services',jobs.length-done.length],['Registered Riders',state.customers.length],['Scheduled Appointments',state.appointments.length]];return `${head('WORKSHOP // DATA INTELLIGENCE','Service Reports','A simple overview of recorded shop activity.',`<button class="button small" data-action="export-jobs">${icon('download')} EXPORT JOBS</button>`)}<div class="shop-summary">${metric('COMPLETED JOBS',num(done.length),'TOTAL','checkCircle')}${metric('RECORDED JOB VALUE',cash(val),'DEMO','chart')}${metric('AVG COMPLETED JOB',cash(avg),'DEMO','speed')}${metric('ACTIVE CUSTOMER COUNT',num(state.customers.length),'RIDERS','users')}</div><div class="content-grid"><section class="panel"><div class="panel-head"><div><div class="label">WORKSHOP OPERATIONS</div><h2>Activity Breakdown</h2></div></div>${row.map(([name,n])=>`<div style="display:flex;justify-content:space-between;gap:12px;border-bottom:1px solid var(--line-soft);padding:15px 0"><span class="text-muted">${esc(name)}</span><strong class="text-cyan">${num(n)}</strong></div>`).join('')}</section><section class="panel"><div class="panel-head"><div><div class="label">REPORT NOTICE</div><h2>Demo Report</h2></div></div><p class="text-muted">These totals summarize the service jobs and customer records saved in this browser. They are not invoices, financial statements, or real shop transaction data.</p><div class="quick-actions"><button class="button small" data-action="export-jobs">${icon('download')} DOWNLOAD CSV</button></div></section></div>`;}
  function settingsPage(role){return `${head('SYSTEM // USER PREFERENCES','Settings','Manage local demo settings and profile information.')}<div class="content-grid"><section class="panel"><div class="panel-head"><div><div class="label">USER PARAMETERS</div><h2>Profile Settings</h2></div></div><form data-form="settings"><div class="field"><label for="settings-name">Display name</label><input name="name" id="settings-name" value="${esc(state.session?.name||'Demo Operator')}" required></div><div class="field"><label for="settings-email">Email address (demo)</label><input name="email" id="settings-email" value="${esc(state.session?.email||'demo@motokare.local')}" type="email" required></div>${role==='shop'?`<div class="field"><label for="settings-shop">Workshop name</label><input name="shopName" id="settings-shop" value="${esc(state.settings.shopName)}" required></div>`:''}<button class="button primary" type="submit">${icon('check')} SAVE PREFERENCES</button></form></section><section class="panel"><div class="panel-head"><div><div class="label">ENVIRONMENT // LOCAL</div><h2>Demo Controls</h2></div></div><p class="text-muted" style="margin-bottom:20px">All entered data is saved only in this browser's local storage. Accounts are simulated and have no server-side security.</p><button class="button danger small" type="button" data-action="reset-demo">${icon('trash')} RESET DEMO DATA</button><div style="border-top:1px solid var(--line-soft);margin-top:25px;padding-top:20px"><span class="pill warn">PHASE 1 & 2 FRONTEND ONLY</span><p style="color:#95BBCB;font-size:11px;margin-top:12px">Production authentication, server database, automated reminder delivery and real workshop synchronization are planned for later phases.</p></div></section></div>`;}
  function notifications(){if(!notifyOpen)return '';const a=state.role==='shop'?state.appointments.filter(x=>x.status==='Pending').map(x=>`${esc(customerName(x.customerId))}: appointment awaiting confirmation.`):allAlerts().slice(0,6).map(x=>`${esc(x.c.name)}: ${x.label.toLowerCase()} (${x.delta<=0?'interval exceeded':num(x.delta)+' km remaining'}).`);return `<aside class="notify-panel" role="dialog" aria-label="Notifications" aria-modal="false"><div class="label">SYSTEM NOTIFICATIONS</div><h3>Attention Queue</h3>${a.length?a.map(x=>`<p>${x}</p>`).join(''):'<div class="notification-empty">No alerts. Everything looks on track.</div>'}</aside>`;}
  function render(){route=routeNow();document.body.classList.remove('app-mode');let content;if(route==='/'||route==='/home')content=landing();else if(route==='/login'||route==='/register')content=authPage(route.slice(1));else{const {role,page}=parseAppRoute(route),valid=(role==='rider'?routesRider:routesShop).map(x=>x[0]);if(!valid.includes(page)){navigate('/');return;}const contentMap=role==='rider'?{dashboard:riderDash,motorcycles:motorcyclesPage,components:componentsPage,maintenance:maintenancePage,history:historyPage,settings:()=>settingsPage('rider')}:{dashboard:shopDash,customers:customersPage,jobs:jobsPage,appointments:appointmentsPage,reports:reportsPage,settings:()=>settingsPage('shop')};content=appShell(role,page,contentMap[page]());}
    app.innerHTML=content + notifications();document.title=`MotoKare | ${route==='/'?'Ride Smart. Maintain Better.':route==='/login'?'Log In':route==='/register'?'Register':breadcrumb(route.split('/').pop())}`;
    // Move keyboard focus only after route navigation initiated by user; avoid auto-scrolling on initial load.
  }
  function field(name,title,type='text',value='',extra=''){return `<div class="field"><label for="f-${name}">${title}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;}
  function selectField(name,title,options,sel){return `<div class="field"><label for="f-${name}">${title}</label><select id="f-${name}" name="${name}" required>${options.map(o=>{const [value,label]=Array.isArray(o)?o:[o,o];return `<option value="${esc(value)}" ${sel===value?'selected':''}>${esc(label)}</option>`;}).join('')}</select></div>`;}
  let lastFocus=null;
  function openModal(type,id=''){
    let title='',subtitle='',fields='',submit='SAVE RECORD',record=null;
    if(type==='add-bike'||type==='edit-bike'){record=state.bikes.find(b=>b.id===id)||null;title=record?'Edit Motorcycle':'Add Motorcycle';subtitle='Enter motorcycle details to maintain a service profile.';fields=`${field('model','Motorcycle make & model','text',record?.model||'','required maxlength="70"') }<div class="form-grid">${field('year','Model year','number',record?.year||2024,'min="1950" max="2100" required')}${field('plate','Plate number (optional)','text',record?.plate||'','maxlength="25"')}</div>${field('odometer','Current odometer (km)','number',record?.odometer||0,'min="0" max="10000000" required')}`;submit=record?'SAVE CHANGES':'ADD MOTORCYCLE';}
    else if(type==='update-mileage'){const b=ensureBike();if(!b)return toast('Please add a motorcycle first.');title='Update Odometer';subtitle=`Current reading: ${num(b.odometer)} km. Only increases are allowed.`;fields=field('odometer','New reading (km)','number',b.odometer,`min="${b.odometer}" max="10000000" required`);submit='UPDATE READING';}
    else if(type==='log-service'){const b=ensureBike();if(!b)return toast('Please add a motorcycle first.');title='Record Maintenance';subtitle='A saved service resets the selected maintenance interval.';const options=activeComps(b.id).map(c=>c.name).concat(['Other Service']);fields=`${selectField('type','Service type',options)}<div class="form-grid">${field('date','Service date','date',today(),'required')}${field('mileage','Odometer at service (km)','number',b.odometer,'min="0" max="10000000" required')}</div><div class="form-grid">${field('cost','Cost (PHP)','number',0,'min="0" step="0.01" required')}${field('shop','Workshop name','text','Self / Local Mechanic','required maxlength="70"')}</div><div class="field"><label for="f-notes">Notes (optional)</label><textarea id="f-notes" name="notes" maxlength="300" placeholder="Parts changed, observations, or details"></textarea></div>`;submit='SAVE SERVICE ENTRY';}
    else if(type==='add-customer'){title='Register Customer';subtitle='Add a motorcycle owner to your workshop registry.';fields=`${field('name','Customer name','text','','required maxlength="80"')}${field('contact','Email or contact information','text','','required maxlength="100"')}${field('motorcycle','Motorcycle model','text','','required maxlength="80"')}${field('odometer','Current mileage (km)','number',0,'min="0" required')}`;submit='REGISTER CUSTOMER';}
    else if(type==='add-job'){if(!state.customers.length)return toast('Add a customer before creating a job.');title='Create Service Job';subtitle='Create a repair/service work order for a registered customer.';fields=`${selectField('customerId','Customer',state.customers.map(c=>[c.id,c.name+' • '+c.motorcycle]))}${field('service','Service description','text','','required maxlength="100"')}<div class="form-grid">${field('date','Job date','date',today(),'required')}${field('cost','Estimated cost (PHP)','number',0,'min="0" step="0.01" required')}</div>${selectField('status','Job status',['Pending','In Progress','Completed'],'Pending')}`;submit='CREATE SERVICE JOB';}
    else if(type==='add-appointment'){if(!state.customers.length)return toast('Add a customer before booking.');title='Book Appointment';subtitle="Plan a customer's next maintenance visit.";fields=`${selectField('customerId','Customer',state.customers.map(c=>[c.id,c.name+' • '+c.motorcycle]))}${field('service','Requested service','text','','required maxlength="100"')}<div class="form-grid">${field('date','Date','date',dateShift(1),`min="${today()}" required`)}${field('time','Time','time','09:00','required')}</div>`;submit='BOOK APPOINTMENT';}
    else return;
    lastFocus=document.activeElement;
    modalRoot.innerHTML=`<div class="overlay" data-action="overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button type="button" class="icon-button modal-close" data-action="close-modal" aria-label="Close dialog">${icon('x')}</button><div class="label">MOTOKARE // DATA ENTRY</div><h2 id="modal-title">${title}</h2><p class="modal-sub">${subtitle}</p><form data-form="${type}" data-id="${esc(id)}">${fields}<div class="form-footer"><button type="button" class="button ghost" data-action="close-modal">CANCEL</button><button type="submit" class="button primary">${icon('check')} ${submit}</button></div></form></section></div>`;
    $('#modal-root .modal-close')?.focus();document.body.style.overflow='hidden';
  }
  function closeModal(){modalRoot.innerHTML='';document.body.style.overflow='';lastFocus?.focus?.();}
  function formVal(form){const d=new FormData(form);return Object.fromEntries(d.entries());}
  function handleForm(form){const type=form.dataset.form,v=formVal(form);const toNumber=x=>Number(x||0);const ride=ensureBike();
    if(type==='login'||type==='register'){
      if(type==='register'&&String(v.fullName).trim().length<2)return toast('Please enter a valid name.');
      if(String(v.password).length<6)return toast('Use at least 6 characters for the demo password.');
      if(type==='register'&&state.role==='shop')state.settings.shopName=(v.shopName||'MotoKare Service Hub').trim();
      state.session={name:type==='register'?v.fullName.trim():state.session?.name||'Demo Operator',email:v.email.trim(),mode:state.role};
      save();navigate('/'+state.role+'/dashboard');toast('Welcome to the MotoKare frontend demo.');return;
    }
    if(type==='settings'){state.session={...(state.session||{}),name:v.name.trim(),email:v.email.trim()};if(v.shopName)state.settings.shopName=v.shopName.trim();save();render();toast('Demo preferences saved.');return;}
    if(type==='add-bike'||type==='edit-bike'){
      const existing=type==='edit-bike'?state.bikes.find(b=>b.id===form.dataset.id):null;
      const payload={model:v.model.trim(),year:toNumber(v.year),plate:v.plate.trim(),odometer:toNumber(v.odometer),updated:today()};
      if(existing){Object.assign(existing,payload);}
      else{const id=uid();state.bikes.push({id,...payload});state.selectedBike=id;state.components.push(...componentCatalog.map((c,i)=>({id:uid(),bikeId:id,name:c.name,icon:c.icon,interval:c.interval,lastKm:payload.odometer,nextKm:payload.odometer+c.interval,dueDate:dateShift(30+i*20)})));}
      save();closeModal();render();toast(existing?'Motorcycle updated.':'Motorcycle added to your garage.');return;
    }
    if(type==='update-mileage'){const newMiles=toNumber(v.odometer);if(newMiles<ride.odometer)return toast('The new reading must not be below the current odometer.');ride.odometer=newMiles;ride.updated=today();save();closeModal();render();toast('Odometer updated. Maintenance estimates recalculated.');return;}
    if(type==='log-service'){
      const mileage=toNumber(v.mileage),c=activeComps(ride.id).find(x=>x.name===v.type);
      if(mileage>ride.odometer+100000)return toast('Please check the entered service mileage.');
      state.services.unshift({id:uid(),bikeId:ride.id,type:v.type,date:v.date,mileage,cost:toNumber(v.cost),shop:v.shop.trim(),notes:v.notes.trim()});
      if(mileage>ride.odometer){ride.odometer=mileage;ride.updated=today();}
      if(c){c.lastKm=mileage;c.nextKm=mileage+c.interval;const d=new Date(v.date+'T12:00:00');d.setMonth(d.getMonth()+6);c.dueDate=d.toISOString().slice(0,10);}
      save();closeModal();render();toast('Service saved; applicable interval updated.');return;
    }
    if(type==='add-customer'){state.customers.unshift({id:uid(),name:v.name.trim(),contact:v.contact.trim(),motorcycle:v.motorcycle.trim(),odometer:toNumber(v.odometer),lastVisit:today()});save();closeModal();render();toast('Customer added to local registry.');return;}
    if(type==='add-job'){state.jobs.unshift({id:uid(),customerId:v.customerId,service:v.service.trim(),date:v.date,status:v.status,cost:toNumber(v.cost)});save();closeModal();render();toast('Service job created.');return;}
    if(type==='add-appointment'){state.appointments.unshift({id:uid(),customerId:v.customerId,service:v.service.trim(),date:v.date,time:v.time,status:'Pending'});save();closeModal();render();toast('Appointment added to the local schedule.');return;}
  }
  function downloadCsv(name,rows){if(!rows.length){toast('No records to export.');return;}const keys=Object.keys(rows[0]);const csv=[keys.join(','),...rows.map(r=>keys.map(k=>'"'+String(r[k]??'').replaceAll('"','""')+'"').join(','))].join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('CSV export prepared.');}
  function clickAction(el,e){const a=el.dataset.action;const id=el.dataset.id;
    if(a==='overlay'){if(e.target===el)closeModal();return;}
    if(a==='close-modal'){closeModal();return;}
    if(a==='sidebar-toggle'){mobileOpen=!mobileOpen;render();return;}
    if(a==='sidebar-close'){mobileOpen=false;render();return;}
    if(a==='mobile-nav'){const n=$('#site-nav');n?.classList.toggle('open');el.setAttribute('aria-expanded',n?.classList.contains('open')?'true':'false');return;}
    if(a==='scroll'){e.preventDefault();if(routeNow()!=='/'){navigate('/');setTimeout(()=>$('#'+el.dataset.target)?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'}),20);}else{$('#site-nav')?.classList.remove('open');$('#'+el.dataset.target)?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'});}return;}
    if(a==='auth-role'){state.role=el.dataset.role;save();render();return;}
    if(a==='switch-role'){mobileOpen=false;notifyOpen=false;navigate('/'+el.dataset.role+'/dashboard');toast('Switched demo workspace.');return;}
    if(a==='notifications'){notifyOpen=!notifyOpen;render();return;}
    if(a==='logout'){state.session=null;save();mobileOpen=false;notifyOpen=false;navigate('/');toast('Exited demo workspace.');return;}
    if(['add-bike','edit-bike','update-mileage','log-service','add-customer','add-job','add-appointment'].includes(a)){openModal(a,id);return;}
    if(a==='select-bike'){state.selectedBike=id;save();render();toast('Active motorcycle changed.');return;}
    if(a==='advance-job'){let j=state.jobs.find(x=>x.id===id);if(j){j.status=j.status==='Pending'?'In Progress':'Completed';save();render();toast('Job status updated: '+j.status+'.');}return;}
    if(a==='confirm-appointment'){let p=state.appointments.find(x=>x.id===id);if(p){p.status='Confirmed';save();render();toast('Appointment confirmed (demo only).');}return;}
    if(a==='export-services'){const bike=ensureBike();downloadCsv('motokare-service-history.csv',state.services.filter(x=>x.bikeId===bike?.id).map(s=>({date:s.date,service:s.type,mileage_km:s.mileage,workshop:s.shop,cost_php:s.cost,notes:s.notes})));return;}
    if(a==='export-jobs'){downloadCsv('motokare-shop-jobs.csv',state.jobs.map(s=>({job_id:s.id,customer:customerName(s.customerId),service:s.service,date:s.date,status:s.status,value_php:s.cost})));return;}
    if(a==='reset-demo'){if(confirm('Reset all local MotoKare demo records? This cannot be undone.')){state=seed();save();navigate('/rider/dashboard');toast('Demo records have been reset.');}return;}
  }
  document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el)clickAction(el,e);else if(notifyOpen&&!e.target.closest('.notify-panel')){notifyOpen=false;render();}});
  document.addEventListener('submit',e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();handleForm(form);});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(modalRoot.innerHTML)closeModal();else if(notifyOpen){notifyOpen=false;render();}else if(mobileOpen){mobileOpen=false;render();}}if(e.key==='Tab'&&modalRoot.innerHTML){const links=[...modalRoot.querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled])')];if(!links.length)return;const first=links[0],last=links[links.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
  window.addEventListener('hashchange',()=>{mobileOpen=false;notifyOpen=false;closeModal();render();window.scrollTo({top:0,behavior:'auto'});});
  render();
})();
